// The days a case needs: every step's day and every day of its play ranges.
export function caseDays(c) {
  const out = new Set();
  for (const s of c.steps) {
    out.add(s.day);
    if (s.play) for (let t = Date.parse(`${s.play[0]}T00:00:00Z`); t <= Date.parse(`${s.play[1]}T00:00:00Z`); t += 86400e3) out.add(new Date(t).toISOString().slice(0, 10));
  }
  return [...out].sort();
}

// Whether the archive (its days' dates) still holds a case: {ok, first, last,
// missing: [dates]}. A case is ok when every step's own day is there; days
// missing inside a play range are only skipped.
export function caseStatus(c, dates) {
  const have = new Set(dates), days = caseDays(c);
  const missingSteps = c.steps.map((s) => s.day).filter((d) => !have.has(d));
  return { ok: missingSteps.length === 0, first: days[0], last: days.at(-1), missing: days.filter((d) => !have.has(d)) };
}

// Index of a date in the archive's days, or -1.
export function dayIndex(days, date) {
  return days.findIndex((d) => d.date === date);
}
